#!/usr/bin/env python3
"""Generate the sticky-error opcode proof with the existing opcode enumeration."""
from pathlib import Path
root = Path(__file__).resolve().parents[2]
source = root / 'lean/Smb/Routine/PpuSchedExec.lean'
s = source.read_text()
s = s.replace('-- Generated from Smb/RefineExec.lean. Do not edit.',
              '-- Generated by analysis/tools/gen_unmodelled_exec.py.')
s = s.replace('import Smb.Routine.PpuSched', 'import Smb.Routine.UnmodelledSticky')
s = s.replace("Every opcode's execution keeps the PPU's event schedule.",
              'No opcode can clear a model-error flag.')
s = s.replace('namespace Smb.Pres', 'namespace Smb.Sticky\nopen Smb.Routine.PpuFrame')
s = s.replace(' : Pres ', ' : UF ').replace('pres_tac', 'sticky_tac')
s = s.replace('Pres.bind', 'Sticky.bind').replace('end Smb.Pres', 'end Smb.Sticky')
(root / 'lean/Smb/Routine/UnmodelledExec.lean').write_text(s)
